"use strict";
import { useVeABXLock } from "hooks/useVeABXLocks";
import { useVotedLocks } from "hooks/useVotedLocks";
import { useCallback, useEffect, useMemo } from "react";
import { Flex, Switch, Text } from "ui/src";
import { Orbit } from "ui/src/components/icons";
import { MAX_LOCK_DURATION_SECONDS, secondsToDays } from "utils/lockCalculations";
import { useModifyLockContext } from "../ModifyLockContextProvider";
import RangeInput from "./Range";
export default function Extend() {
  const { selectedLockId, formData, updateFormData } = useModifyLockContext();
  const { data: currentLock } = useVeABXLock(selectedLockId || void 0);
  const { hasVoted: checkHasVoted } = useVotedLocks(currentLock ? [currentLock] : []);
  const hasActiveVotes = currentLock ? checkHasVoted(currentLock.id) : false;
  const { remainingDays, maxExtensionDays, maxLockDays, isAlreadyPermanent } = useMemo(() => {
    const currentTimeSeconds = Math.floor(Date.now() / 1e3);
    const currentUnlockTime = currentLock ? parseInt(currentLock.lockEnd) : currentTimeSeconds;
    const remaining = Math.max(0, secondsToDays(currentUnlockTime - currentTimeSeconds));
    const maxDays = secondsToDays(MAX_LOCK_DURATION_SECONDS);
    const maxExtension = maxDays - remaining;
    const isPermanent = currentLock?.permanent || false;
    return {
      remainingDays: remaining,
      maxLockDays: maxDays,
      maxExtensionDays: maxExtension,
      isAlreadyPermanent: isPermanent
    };
  }, [currentLock]);
  const handlePermanentLockToggle = useCallback(
    (checked) => {
      if (isAlreadyPermanent && hasActiveVotes) {
        updateFormData({ unlockPermanent: false });
        return;
      }
      if (isAlreadyPermanent) {
        updateFormData({
          unlockPermanent: !checked,
          extendToMaxLock: false,
          extendDays: 0
        });
        return;
      }
      updateFormData({
        extendToMaxLock: checked,
        extendDays: checked ? 0 : formData.extendDays,
        unlockPermanent: false
      });
    },
    [isAlreadyPermanent, hasActiveVotes, formData.extendDays, updateFormData]
  );
  useEffect(() => {
    if (isAlreadyPermanent) {
      if (formData.extendToMaxLock) {
        updateFormData({ extendToMaxLock: false });
      }
      if (hasActiveVotes && formData.unlockPermanent) {
        updateFormData({ unlockPermanent: false });
      }
    } else if (formData.unlockPermanent) {
      updateFormData({ unlockPermanent: false });
    }
  }, [isAlreadyPermanent, hasActiveVotes, formData.extendToMaxLock, formData.unlockPermanent, updateFormData]);
  const switchChecked = isAlreadyPermanent ? !formData.unlockPermanent : formData.extendToMaxLock;
  return <Flex mt={"$gap36"}>
      <Flex borderWidth={1} borderColor={"$surface3"} borderRadius={"$rounded12"} p={"$padding12"}>
        <Flex row gap={"$gap12"} alignItems="center">
          <Switch
    variant="branded"
    switchSize="small"
    checked={switchChecked}
    onCheckedChange={handlePermanentLockToggle}
    disabled={isAlreadyPermanent && hasActiveVotes}
  />
          <Text variant="buttonLabel3">Permanent Lock Mode</Text>
          <Orbit size={20} color="$neutral3" />
        </Flex>

        <Text variant="body4" mt={"$gap12"}>
          {isAlreadyPermanent ? formData.unlockPermanent ? "Permanent mode will be disabled, converting this position into a new 4 year lock (rounded to the next full week). You can extend or shorten after disabling." : hasActiveVotes ? "This lock is currently permanent and has active votes. Reset votes before disabling permanent mode." : "This lock is currently permanent with maximum 1-to-1 voting power. Toggle off to convert it into a fresh 4 year time-based lock." : "When activated, converts this lock to a permanent lock with maximum 1-to-1 voting power. Permanent locks never expire and don't need to be extended."}
        </Text>

        {isAlreadyPermanent && !formData.unlockPermanent && <Text variant="body4" mt={"$gap12"} color="$neutral2Temp">
            ✓ Lock is currently permanent
          </Text>}
      </Flex>

      {!isAlreadyPermanent && !formData.extendToMaxLock && maxExtensionDays > 0 && <RangeInput
    value={formData.extendDays}
    onChange={(days) => updateFormData({ extendDays: days })}
    min={0}
    max={maxExtensionDays}
    label={`Extend by ${formData.extendDays} days`}
  />}

      {!isAlreadyPermanent && formData.extendToMaxLock && <Flex mt={"$gap24"} p={"$padding12"} borderWidth={1} borderColor={"$accent1"} borderRadius={"$rounded12"}>
          <Text variant="body3" color="$neutral2Temp">
            Will convert to permanent lock with maximum voting power (1:1 ratio)
          </Text>
        </Flex>}

      {isAlreadyPermanent && hasActiveVotes && <Flex mt={"$gap24"} p={"$padding12"} borderWidth={1} borderColor={"$statusCritical"} borderRadius={"$rounded12"}>
          <Text variant="body3" color="$statusCritical">
            Reset votes before disabling permanent mode.
          </Text>
        </Flex>}

      {isAlreadyPermanent && formData.unlockPermanent && !hasActiveVotes && <Flex mt={"$gap24"} p={"$padding12"} borderWidth={1} borderColor={"$accent1"} borderRadius={"$rounded12"}>
          <Text variant="body3" color="$neutral2Temp">
            Will disable permanent mode and convert back into a 4 year lock (rounded to the next full week)
          </Text>
        </Flex>}

      {!isAlreadyPermanent && maxExtensionDays <= 0 && !formData.extendToMaxLock && <Flex mt={"$gap24"} p={"$padding12"} borderWidth={1} borderColor={"$neutral3"} borderRadius={"$rounded12"}>
          <Text variant="body3" color="$neutral2">
            This lock is already at maximum duration. You can convert it to a permanent lock for maximum voting power.
          </Text>
        </Flex>}
    </Flex>;
}
