"use strict";
import { createContext, useContext, useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";
export const ModifyLockContext = createContext(null);
export const ModifyLockProvider = ({ children }) => {
  const [searchParams] = useSearchParams();
  const tabFromUrl = searchParams.get("tab");
  const lockIdFromUrl = searchParams.get("lockId");
  const [activeOption, setActiveOption] = useState(
    tabFromUrl && ["Increase", "Extend", "Merge", "Transfer", "Reset"].includes(tabFromUrl) ? tabFromUrl : "Increase"
  );
  const [selectedLockId] = useState(lockIdFromUrl);
  const [formData, setFormData] = useState({
    increaseAmount: "",
    extendDays: 0,
    extendToMaxLock: false,
    unlockPermanent: false,
    selectedMergeLockId: "",
    transferToAddress: ""
  });
  const updateFormData = (updates) => {
    setFormData((current) => ({ ...current, ...updates }));
  };
  useEffect(() => {
    if (tabFromUrl && ["Increase", "Extend", "Merge", "Transfer", "Reset"].includes(tabFromUrl)) {
      setActiveOption(tabFromUrl);
    }
  }, [tabFromUrl]);
  return <ModifyLockContext.Provider value={{
    setActiveOption,
    activeOption,
    selectedLockId,
    formData,
    updateFormData
  }}>
      {children}
    </ModifyLockContext.Provider>;
};
export const useModifyLockContext = () => {
  const context = useContext(ModifyLockContext);
  if (!context) {
    throw new Error("useModifyLock must be used within a ModifyLockProvider");
  }
  return context;
};
