"use strict";
import { Flex, Text as UiText, styled } from "ui/src";
import { formatVotingPower } from "utils/lockCalculations";
const Text = styled(UiText, {
  textAlign: "right"
});
const FlexWrapper = styled(Flex, {
  flex: 1,
  width: "100%",
  flexDirection: "column",
  className: "lock-time",
  p: "$padding12",
  borderRadius: "$rounded12",
  gap: "$gap8",
  backgroundColor: "$surface2Hovered"
});
export default function LockTimeAndVotingPower({
  votingPower = "0",
  lockDuration = 0
}) {
  const formatLockTime = (days) => {
    if (days === 0) return "Permanent";
    if (days < 30) return `${days} days`;
    if (days < 365) {
      const months = Math.round(days / 30);
      return `${months} month${months > 1 ? "s" : ""}`;
    }
    const years = Math.floor(days / 365);
    const remainingDays = days % 365;
    if (remainingDays === 0) return `${years} year${years > 1 ? "s" : ""}`;
    const remainingMonths = Math.round(remainingDays / 30);
    if (remainingMonths === 0) return `${years} year${years > 1 ? "s" : ""}`;
    if (years === 3 && remainingMonths >= 12) {
      return "4 years";
    }
    return `${years} year${years > 1 ? "s" : ""} ${remainingMonths} month${remainingMonths > 1 ? "s" : ""}`;
  };
  return <Flex row justifyContent="space-between" gap={"$gap12"} $md={{ flexDirection: "column" }}>
      <FlexWrapper>
        <Text variant="body3" color={"$neutral3"}>
          Lock time
        </Text>
        <Text variant="heading3">{formatLockTime(lockDuration)}</Text>
      </FlexWrapper>
      <FlexWrapper>
        <Text variant="body3" color={"$neutral3"}>
          Estimated voting power
        </Text>
        <Text variant="heading3">{formatVotingPower(votingPower)} veABX</Text>
      </FlexWrapper>
    </Flex>;
}
